@RestController
public class UserController {
    @Autowired
    private UserService userService;

    @PostMapping("/users")
    public User saveUser(@RequestBody User user) {
        RetryConfig config = RetryConfig.getRetryConfig();
        return userService.saveUser(user, config);
    }

    private User saveUser(User user, RetryConfig config) {
        int retries = 0;
        while (retries < config.getMaxRetries()) {
            try {
                return userRepository.save(user);
            } catch (TransientException e) {
                retries++;
                long delay = calculateDelay(config.getInitialDelay(), config.getBackoffFactor());
                Thread.sleep(delay); // wait for calculated delay before retrying
            }
        }
        throw new RuntimeException("Failed to save user after " + config.getMaxRetries() + " retries");
    }

    private long calculateDelay(long initialDelay, double backoffFactor) {
        return (long) (initialDelay * Math.pow(backoffFactor, retries));
    }
